import type { VisualAttributes } from './attributes';

/**
 * Where a WordPress article came from. `omniflow_article` = written by the
 * WordPress generator (wordpress_generations); `external_wordpress_post` =
 * an existing post read from a connected site, never generated by OmniFlow.
 */
export type ArticleSourceType = 'omniflow_article' | 'external_wordpress_post';

export interface ArticleImage {
  /** Absolute http(s) URL. Reference only — never a Pin destination. */
  url: string;
  alt: string;
  caption: string;
  /** Section the image appears in (null for the featured image). */
  sectionId: string | null;
}

/**
 * - `intro`: text before the first heading.
 * - `subject`: something the article actually presents (a pattern, a
 *   project, an idea) — what a Pin may depict.
 * - `support`: useful context (how-to, tips) that is not a subject.
 * - `faq`: question / answer blocks.
 * Related-post / "explore more" blocks are dropped during extraction and
 * never reach a context.
 */
export type ArticleSectionKind = 'intro' | 'subject' | 'support' | 'faq';

export interface ArticleSection {
  /** Stable within one extraction: s0 (intro), s1, s2… in document order. */
  id: string;
  level: 1 | 2 | 3;
  heading: string;
  /** Heading without its list number ("3. Neapolitan Scarf" → "Neapolitan Scarf"). */
  subject: string;
  kind: ArticleSectionKind;
  /** Cleaned, URL-free, neutralized section text (paragraphs joined by "\n"). */
  text: string;
  images: ArticleImage[];
  attributes: VisualAttributes;
}

/**
 * The single article model both Pinterest sources share. Every text field is
 * already URL-free and neutralized; `permalink` is kept for internal
 * traceability only — it is never sent to a model and never becomes a
 * destination URL.
 */
export interface WordPressArticleContext {
  sourceType: ArticleSourceType;
  /** wordpress_sites.id — external posts only. */
  siteId: string | null;
  wordpressPostId: number | null;
  /** wordpress_generations.id — OmniFlow articles only. */
  omniflowArticleId: string | null;
  title: string;
  excerpt: string;
  plainText: string;
  headings: Array<{ level: 1 | 2 | 3; text: string }>;
  sections: ArticleSection[];
  /** True when at least three headings are numbered list items. */
  isListicle: boolean;
  materials: string[];
  colors: string[];
  techniques: string[];
  patterns: string[];
  shapes: string[];
  textures: string[];
  objects: string[];
  /** Short descriptive sentences taken verbatim from the article. */
  visualDetails: string[];
  featuredImage: ArticleImage | null;
  internalImages: ArticleImage[];
  imageAltTexts: string[];
  categories: string[];
  tags: string[];
  language: string;
  permalink: string | null;
}
